 def el(parent,ns_uri,localname,**attrs):return X.SubElement(parent,'{'+ns_uri+'}'+localname,{k:str(v) for k,v in attrs.items()})
 inline=el(dr,WP,'inline',distT=0,distB=0,distL=0,distR=0);cx=9000000;cy=5625000
 el(inline,WP,'extent',cx=cx,cy=cy);el(inline,WP,'docPr',id=100+figure_no,name=info['title'],descr=info['title'])
 gr=el(inline,A,'graphic');gd=el(gr,A,'graphicData',uri=PIC);pic=el(gd,PIC,'pic');nv=el(pic,PIC,'nvPicPr');el(nv,PIC,'cNvPr',id=0,name=filename);el(nv,PIC,'cNvPicPr')
 bf=el(pic,PIC,'blipFill');bl=el(bf,A,'blip');bl.set('{'+R+'}embed',rid);st=el(bf,A,'stretch');el(st,A,'fillRect')
 sp=el(pic,PIC,'spPr');xf=el(sp,A,'xfrm');el(xf,A,'off',x=0,y=0);el(xf,A,'ext',cx=cx,cy=cy);pg=el(sp,A,'prstGeom',prst='rect');el(pg,A,'avLst')
 p(f'Рисунок {figure_no} — {info["title"]}','L3Caption',center=True)
