def trace(num):
 if num<=8:return 'A1','P1','D1','S1'
 if num<=23:return 'A2','P2','D2, D3','S2'
 if num<=36:return 'A3','P3','D3, D8','S2, S4' if num>=31 else 'S2'
 if num<=46:return 'A3, A4','P3, P4','D3, D4','S3, S4'
 if num<=48:return 'A2, A3','P2, P3','D2, D3','S2, S3'
 if num<=55:return 'A5','P3, P5','D3–D5','S3'
 if num<=65:return 'A3–A5','P3–P5','D3–D5','S5'
 if num<=75:return 'A3, A5','P3, P5, P6','D3, D5, D8','S6'
 if num<=77:return 'A3','P3, P4','D3–D5','S2, S5'
 if num<=79:return 'A6','P1–P6','D1–D8' if num==78 else 'D7','S1–S8'
 if num<=81:return 'A1','P1–P6','D1','S1, S7, S8'
 if num<=83:return 'A4','P3, P4','D3, D4','S3, S4'
 if num==84:return 'A3, A5','P3, P5, P6','D3, D5, D8','S6'
 if num==85:return 'A4','P4','D4','S3, S5'
 if num==86:return 'A3','P3, P6','D3, D8','S6'
 if num<=89:return 'A2, A6','P1, P2, P6','D2, D6','S7'
 if num<=92:return 'A1, A6','P1, P6','D1, D6–D8','S8'
 if num==93:return 'A4','P4','D4, D7, D8','S5'
 return 'A2, A6','P2, P6','D2, D6','S7'
traces=[]
